<section class="jura-card"><h1>Pages</h1><?php if (!empty($pages)): ?><table class="jura-table"><thead><tr><th>ID</th><th>Title</th><th>Slug</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($pages as $p): ?><tr><td><?=e($p['id'])?></td><td><?=e($p['title'])?></td><td><?=e($p['slug'])?></td><td><?=e($p['status'])?></td><td><?=e($p['created_at'])?></td></tr><?php endforeach;?></tbody></table><?php else: ?><p>No pages yet.</p><?php endif;?></section>
